using System; using System.Drawing; using System.Windows.Forms;
namespace ProyectoMatematicoWinForms { public class ResultadosForm:Form { public ResultadosForm(string[] n,int[] p,int c){Text="Proyecto Matemático - Resultados";StartPosition=FormStartPosition.CenterScreen;Size=new Size(600,430);Controls.Add(new Label{Text="RESULTADOS Y RANKING",Font=new Font("Segoe UI",20,FontStyle.Bold),AutoSize=true,Location=new Point(145,35)});var l=new ListBox{Location=new Point(120,125),Size=new Size(360,150),Font=new Font("Segoe UI",12)};for(int i=0;i<c;i++)l.Items.Add((i+1)+". "+n[i]+" - "+p[i]+" puntos");Controls.Add(l);if(c==2)Controls.Add(new Label{Text=p[0]==p[1]?"Resultado: EMPATE":"Ganador: "+n[0],Font=new Font("Segoe UI",13,FontStyle.Bold),AutoSize=true,Location=new Point(210,295)});var b=new Button{Text="Cerrar",Location=new Point(230,345),Size=new Size(140,38)};b.Click+=(s,e)=>Close();Controls.Add(b);} } }
